package com.bank.queue;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ArrayQueueDemo {

    private static final Logger log = Logger.getLogger(ArrayQueueDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Cheque-clearing tray can hold only 3 cheques at once.
        ArrayQueue queue = new ArrayQueue(3);

        queue.enqueue("CHQ-1001");
        queue.enqueue("CHQ-1002");
        queue.enqueue("CHQ-1003");
        log.info(() -> "Tray full? " + queue.isFull());

        // Clerk processes two cheques from the front, freeing two slots.
        log.info(() -> "Processed: " + queue.dequeue());
        log.info(() -> "Processed: " + queue.dequeue());

        // Two new cheques arrive; rear pointer wraps around to reuse freed slots.
        queue.enqueue("CHQ-1004");
        queue.enqueue("CHQ-1005");

        log.info(() -> "Front cheque now: " + queue.peek());
        while (!queue.isEmpty()) {
            log.info(() -> "Processed: " + queue.dequeue());
        }
        log.info("All cheques cleared.");
    }
}

