class ArrayQueue {

    private static final Logger log = Logger.getLogger(ArrayQueue.class.getName());

    private final String[] items;   // fixed backing array
    private final int capacity;      // maximum number of cheques
    private int front;               // index of the oldest element
    private int rear;                // index of the next free slot
    private int count;               // how many elements currently stored

    ArrayQueue(int capacity) {
        this.capacity = capacity;
        this.items = new String[capacity];
        this.front = 0;
        this.rear = 0;
        this.count = 0;
    }

    // enqueue: add at the rear, wrap with modulo.
    void enqueue(String chequeNo) {
        if (isFull()) {
            log.warning("Tray full — cannot enqueue " + chequeNo);
            throw new IllegalStateException("Queue is full");
        }
        items[rear] = chequeNo;
        rear = (rear + 1) % capacity; // wrap around
        count++;
        log.info(() -> "ENQUEUE " + chequeNo + " (size=" + count + ")");
    }

    // dequeue: remove from the front, wrap with modulo.
    String dequeue() {
        if (isEmpty()) {
            throw new java.util.NoSuchElementException("Queue is empty");
        }
        String value = items[front];
        items[front] = null;          // help garbage collection
        front = (front + 1) % capacity; // wrap around
        count--;
        return value;
    }

    String peek() {
        if (isEmpty()) throw new java.util.NoSuchElementException("Queue is empty");
        return items[front];
    }

    boolean isEmpty() { return count == 0; }
    boolean isFull() { return count == capacity; }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
